        SettingOption(id: "pointing.textEntry", section: .assistant, group: "Desktop pointing", title: "Double-tap Control to type a question", note: "Two quick taps on Control open a small box to type a question about what is under your pointer. Off by default.", kind: .toggle, choices: [], range: nil, defaultValue: "false", state: .live, todo: "macOS Dictation can also use \"Press Control key twice\" (System Settings, Keyboard). If both are on, both fire. Turn one off."),
        SettingOption(id: "pointing.dictationFnControl", section: .assistant, group: "Desktop pointing", title: "Use Fn+Control for dictation", note: "Sets the dictation key to Fn+Control. Turning it off puts your previous dictation key back.", kind: .toggle, choices: [], range: nil, defaultValue: "false", state: .live, todo: "Off by default. Fn (Globe) alone is used by macOS for emoji and Dictation; check System Settings, Keyboard."),
